import json

class SearchLeakix:
    def __init__(self, word: str, json_module: ModuleType = None, core_instance: Core = None):
        self.word = word
        self.totalhosts: set = set()
        self.totalemails: set = set()
        self.proxy = False
        self.hostname = 'https://leakix.net'

        if json_module:
            self.json = json_module
        else:
            self.json = _stdlib_json

        if core_instance:
            self.core = core_instance
        else:
            self.core = Core()

    def fetch_data(self, url: str) -> list:
        response = self._fetch_url(url)
        return [self._safe_parse_json(json_response) for json_response in response]

    def _fetch_url(self, url: str) -> list:
        headers = {
            'User-agent': self.core.get_user_agent(),
            'accept': 'application/json',
        }

        if self.core.leakix_key():
            headers['api-key'] = self.core.leakix_key()

        response = AsyncFetcher.fetch_all([url], headers=headers, proxy=self.proxy)
        return response

    def _safe_parse_json(self, json_response: str) -> list:
        data = json.loads(json_response)
        return [item for item in data if isinstance(item, dict)]

    async def do_search(self):
        query_string = f'{self.hostname}/api/subdomains/{self.word} or {self.hostname}/api/host/{self.word}'
        response_urls = await self.fetch_data(query_string)

        for response in response_urls:
            try:
                items = self._safe_parse_json(response)
                if items:
                    for item in items:
                        hostname = item.get('hostname', '') or item.get('host', '') or item.get('domain', '')
                        if hostname and (hostname.endswith(f'.{self.word}') or hostname == self.word):
                            self.totalhosts.add(hostname.lower())

                        email = item.get('email', '') or item.get('username', '')
                        if email and '@' in email and self.word in email:
                            self.totalemails.add(email.lower())

                        subdomain = item.get('subdomain', '')
                        if subdomain and (subdomain.endswith(f'.{self.word}') or subdomain == self.word):
                            self.totalhosts.add(subdomain)
            except Exception as e:
                print(f'Failed to parse response: {e}')

    async def fetch_all(self, urls: list) -> list:
        responses = []
        for url in urls:
            try:
                response = await AsyncFetcher.fetch_all([url], headers=headers, proxy=self.proxy)
                responses.extend(response)
            except Exception as e:
                print(f'Failed to fetch URL {url}: {e}')
